"""Original bilingual recipe blueprints. Quantities are per reference serving."""
from __future__ import annotations


def L(food, grams, role="support"):
    return {"ingredient_id": food, "quantity": grams, "unit": "g", "variety_role": role}


def S(en, es):
    return {"en": en, "es": es}


def C(kind, en, es, lines, steps, optional=False):
    return {"id": kind, "kind": kind, "name": S(en, es), "optional": optional,
            "default_included": not optional, "ingredients": lines, "instructions": steps}


def R(identifier, en, es, main, steps, *, breakfast=False, side=None, prep=10, cook=20):
    components = [C("main", en, es, main, steps)]
    if side:
        components.append(C("side", *side))
    return {"id": identifier, "name": S(en, es), "meal_types": ["breakfast"] if breakfast else ["lunch", "dinner"],
            "reference_servings": 1, "active_prep_minutes": prep, "finishing_cook_minutes": cook,
            "components": components, "provenance": {"kind": "original_repository_content", "copied_recipe_text": False},
            "review_status": "desk_validated_not_kitchen_tested"}


def grain(food, grams=60):
    return ("Grain accompaniment", "Guarnición de cereal", [L(food, grams, "base")],
            [S("Cook the weighed dry grain using its preparation instructions; serve with the main dish.",
               "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal.")])


def bread(grams=60):
    return ("Wholemeal bread", "Pan integral", [L("bread", grams, "base")],
            [S("Serve the weighed bread plain or lightly toasted; add no unlisted butter or oil.",
               "Sirve el pan pesado, solo o ligeramente tostado; no añadas mantequilla ni aceite que no figuren en la receta.")])


