def blueprints():
    import copy
    result = copy.deepcopy(RECIPES)
    for index, recipe in enumerate(r for r in result if r["id"].startswith("m")):
        en, es, lines, step = copy.deepcopy(DESSERTS[index % len(DESSERTS)])
        recipe["components"].append(C("dessert", en, es, lines, [step], optional=True))
    return result
